import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForEco4,validEco4,advanceEco4,numericEco4}from './eco4-models.js?v=20261023-physicscomplete01';import{showEco4}from './eco4-visuals.js?v=20261023-physicscomplete01';export{showEco4};
export function mountEco4(l,p,root,{save,done,feedback}){let ts=tasksForEco4(l.widget.slice(5)),w=p.widget;w.eco4Task??=ts[0].id;w.eco4Drafts??={};w.eco4Passed??=[];let i=ts.findIndex(t=>t.id===w.eco4Task);if(i<0)i=0;let t=ts[i],v=w.eco4Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountEco4(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.eco4Passed.includes(t.id));
syncProcessMovie(l,1,{process:false});
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('eco4Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('eco4Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealEco4">Reveal evidence →</button><p id="eco4Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showEco4(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#eco4Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validEco4(c,v.answer);}
else if(t.type==='sequence'){body=field('eco4Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceEco4">Advance pathway →</button><p id="eco4Readout" aria-live="polite"></p>';draw=()=>{showEco4(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#eco4Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else{body='<p>'+t.prompt+'</p><label class="field-label" for="eco4Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="eco4Number" type="number" step="any" value="'+(v.number??'')+'">'+field('eco4Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showEco4(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericEco4(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="eco4Evidence"></p><div class="lab-actions"><button class="secondary" id="recordEco4">Record reasoning</button><button class="secondary" id="nextEco4">Next challenge →</button></div><p id="eco4Progress"></p>';
const status=()=>{$('#eco4Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.eco4Passed.includes(t.id)?'Challenge recorded.':'';$('#eco4Progress').textContent=ts.filter(t=>w.eco4Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='eco4Case'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='eco4Answer')v.answer=val;else if(id==='eco4Next')v.next=val;else if(id==='eco4Number')v.number=val;else if(id==='eco4Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v.number=e.target.value;save();};}
if($('#revealEco4'))$('#revealEco4').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validEco4(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validEco4(t.cases[v.case],v.answer));};
if($('#advanceEco4'))$('#advanceEco4').onclick=()=>{let n=advanceEco4(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordEco4').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);let finished=t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.eco4Passed.includes(t.id))w.eco4Passed.push(t.id);p.widgetDone=ts.every(t=>w.eco4Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextEco4').onclick=()=>{if(!w.eco4Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.eco4Task=ts[(i+1)%ts.length].id;save();remount();};}
